// Generated from cards.json. Loaded via <script> so index.html works from file://
window.CARDS = [{"id": 1, "name": "ACTIVISM", "definition": "to work vigorously toward political or social change", "actions": ["Choose one or two causes that feel important to you. Research ways you can get involved, and choose one cause per year on which to focus your time and energy.", "Provide space in your everyday life for the people and causes you want to support.", "Use listening as its own form of activism; hear other perspectives, and commit to changing the status quo.", "Help connect people who need resources with organizations that can offer support.", "Remember, it’s not about you. Engage others in making change instead of attempting to be the hero."], "image": "data/images/01_ACTIVISM.jpg"}, {"id": 2, "name": "ADVENTURE", "definition": "to participate in exciting or stimulating experiences and undertakings", "actions": ["Reframe adventure to include something that can happen anytime, anywhere; attempt to encounter every small task or event in your life with a sense of wonder.", "Take a different route on your daily errands, commute to work, or walks, so you can begin to find moments of adventure in your everyday life.", "Research and discover areas near your hometown that you can explore easily, perhaps on a long weekend.", "Listen to music, make food, and try traditional crafts from places you’d like to visit.", "Assess the areas of your life that seem to limit your ability to have adventure, and take steps to remove those barriers."], "image": "data/images/02_ADVENTURE.jpg"}, {"id": 3, "name": "AMBITION", "definition": "to desire achievement or distinction of some kind", "actions": ["Set concrete, manageable goals for the things you’d like to achieve, and then make a specific plan for how you’ll get to each goal.", "Ask yourself: “What is one area of my work or life in which I can take a risk that could help me get further toward my goals?”", "Focus on what you have control over, and take action on those things first.", "Stay centered on your own journey and not the journeys of other people with similar paths or goals.", "Surround yourself with other people who are similarly ambitious and goal-oriented and can support and inspire you."], "image": "data/images/03_AMBITION.jpg"}, {"id": 4, "name": "ASSERTIVENESS", "definition": "to be confident, self-assured, and able to express needs easily", "actions": ["Aim for open and honest communication when relaying your thoughts, opinions, and preferences. Don’t expect other people to know what you want; speak up and ask for what you need calmly and with confidence.", "Note all the ways you want to be assertive in your communication. Consider starting with written communication first, since it’s sometimes easier to think through, and then move to verbal communication.", "Focus on understanding other people’s points of view to consider all sides of a situation, using statements such as “I think” or “I feel.” Refrain from using aggressive language such as “you always” or “you never.”", "Remember that when you’re assertive, you’re neither passive nor aggressive, but direct and honest.", "Create and name boundaries that help you decide what you will and won’t allow; use them as a filter for how you communicate."], "image": "data/images/04_ASSERTIVENESS.jpg"}, {"id": 5, "name": "BEAUTY", "definition": "to notice, create, cultivate, and surround yourself with beauty", "actions": ["Make a list of all the ways you currently invite beauty into your life.", "Keep your eyes and ears open, honing your senses to pick up on beautiful things that you might otherwise miss. Pay attention to and appreciate the small beauties in your day.", "For a period of time each day, put away your digital screens and spend some time in the physical world.", "Consider making small changes in your living environment so that, everywhere you look, your eye will fall on something you consider beautiful.", "Look for beauty in the people around you—their qualities, how they behave, a choice they make—then comment on it; you’ll find this kind of awareness is contagious!"], "image": "data/images/05_BEAUTY.jpg"}, {"id": 6, "name": "CAREER", "definition": "to prioritize progress in your profession or occupation", "actions": ["Reflect and write about what your career means to you.", "Write down what you want to accomplish in your career, and be able to communicate your goals to others. If you don’t have the career you want yet, write about your dream career.", "Celebrate whenever you have a career achievement.", "Practice advocating for yourself at work whenever you feel you’ve earned something you aren’t getting.", "Identify those who are further in their career than you are—coworkers and others whom you can learn from and emulate; consider asking for their mentorship and guidance."], "image": "data/images/06_CAREER.jpg"}, {"id": 7, "name": "CIVIC ENGAGEMENT", "definition": "to feel a sense of duty to and become involved with your community or municipality", "actions": ["Come up with a list of issues you feel need to be fixed in your community, then consider volunteering your time toward improving the issue that resonates most strongly with you.", "Attend neighborhood or city meetings on occasion to understand how your local government works.", "Help others become engaged by informing them about local issues.", "Read your local paper; this is a good way to inform yourself about local matters, especially when it comes time to vote.", "Most importantly, exercise your right to vote."], "image": "data/images/07_CIVIC_ENGAGEMENT.jpg"}, {"id": 8, "name": "CIVILITY", "definition": "to exercise respect, politeness, and courtesy toward other people in both actions and words", "actions": ["Ask yourself: “How do I define and practice civility in my own life?” and “How do I expect others to treat me?”", "Consider how, through your own observable behaviors, you might influence others to be more civil in their own interactions.", "Make a list of all the ways in which you can take care of your mental and physical health; taking care of your own needs improves your ability to be civil to others.", "Pay attention to how respectful you are of others in all your communications and actions."], "image": "data/images/08_CIVILITY.jpg"}, {"id": 9, "name": "COLLABORATION", "definition": "to work with others for a common purpose or good in the creation of something", "actions": ["Help those you wish to collaborate with by developing clear goals to work toward together, so potential collaborators will understand what they’re signing up for.", "Communicate your expectations with those you wish to collaborate with, and ask them to do the same.", "Understand your own strengths, and work to understand the strengths of those you are working with. This way, each person can use their own skills and talents to work toward the common goal, complementing one another’s contributions.", "Check in with others regularly, as you and your collaborators get used to one another’s working styles. Adjust your practices as needed.", "Practice thinking more creatively, and encourage others to do the same."], "image": "data/images/09_COLLABORATION.jpg"}, {"id": 10, "name": "COMPASSION", "definition": "to have deep sympathy and sorrow for others who are experiencing suffering", "actions": ["Practice self-compassion. Tamp down that inner critic who judges, punishes, or puts you down when you’ve made a mistake. Instead, fill yourself up with a gentler, more nurturing force.", "Consider the notion that we are all interconnected, and work on shifting your perspective away from thinking about how something affects only you or those close to you.", "When speaking with others who need compassion, stay quiet and try not to interrupt, judge, or fix. “Generous listening” is a gateway to compassion.", "Notice when compassion comes easily or spontaneously for you throughout your day. Pay attention to when you resist acknowledging suffering, either your own or others’.", "Recognize when you judge, minimize, or dismiss suffering—for example, by saying it doesn’t count or is insignificant compared to someone else’s pain or something else going on in the world."], "image": "data/images/10_COMPASSION.jpg"}, {"id": 11, "name": "CONTRIBUTION", "definition": "to give time, money, service, or knowledge to make a difference in the world", "actions": ["Create specific and meaningful categories for your contributions so you don’t lose yourself in doing too much.", "Ask yourself: “What am I able to contribute to my buckets today?”", "Brainstorm about the less obvious, everyday ways you can contribute to making a difference in the lives of those in your circle of friends, family, and colleagues.", "Reflect on the impacts you’ve made so far in your life, and notice what gave you the most joy and satisfaction; endeavor to make further contributions in these ways."], "image": "data/images/11_CONTRIBUTION.jpg"}, {"id": 12, "name": "COURAGE", "definition": "to have a mind or spirit that enables you to face difficulty with bravery", "actions": ["Avoid thinking of courage as fearlessness! All humans have fears, and fear is natural; courage is feeling fear and moving forward anyway.", "Remember that courage is a muscle you have to exercise. Over time and with practice, it becomes a habit.", "Embrace vulnerability. Courage and vulnerability cannot live separately from each other.", "Focus your energy on the object of your courage—a principle, a person, a cause—not on what might happen if you fail. Imagine what will happen if you succeed.", "Find other people whom you consider courageous, and use them as role models."], "image": "data/images/12_COURAGE.jpg"}, {"id": 13, "name": "CREATIVITY", "definition": "to use imagination to transcend ordinary thinking and generate new ideas", "actions": ["Notice every day how creativity comes to life around you. Then begin cultivating and practicing moments of it yourself, knowing that building a practice of creativity requires deep wells of patience.", "Expose yourself deliberately to new experiences and to learning; over time, you’ll begin to make new connections between different regions of your brain.", "Capture your first ideas for any creative endeavor, but then make a plan to actualize them.", "Take a break to allow the unconscious part of your brain to process what it’s receiving in new and surprising ways. Consider taking this break outside and away from digital devices. “Sleeping on it” is a great practice!", "Consider how you can use your physical environment to inspire you and nurture your creativity. Do you need plants, natural light, art, scents, candles, music, quiet, or something handy to write on?"], "image": "data/images/13_CREATIVITY.jpg"}, {"id": 14, "name": "CURIOSITY", "definition": "to desire to learn or acquire knowledge about everything and/or about specific topics", "actions": ["Be a “yes” person, responding, “Yes, tell me more!” or “Yes, I’ll try that with you!” Don’t default to “no.”", "Be vigilant in your attempt to make discoveries. Curious people continuously find things that spark their interest.", "Don’t be afraid to show that you don’t know the answer to something; wonder aloud by asking questions.", "Practice being present and engaged. When you’re in the moment with others and your shared experiences, you’re far more likely to be curious.", "Take a week, a month, or a year to become a deep student of something you’re interested in, without attachment to outcome. You might be surprised at where your exploration takes you!"], "image": "data/images/14_CURIOSITY.jpg"}, {"id": 15, "name": "DIVERSITY", "definition": "to honor and appreciate different types of people and ideas", "actions": ["Make an effort to surround yourself and your family with various perspectives and lived experiences, looking for insights you can learn from and apply to make your own life richer. Talk to your neighbors, your colleagues, and others in your community, adopting a humble, I-want-to-learn attitude.", "In your work and life outside work, create a culture that is inclusive and welcoming to everyone. Understand that when people don’t see their identities reflected, they feel a lesser sense of belonging.", "Recognize that diversity of thought and experience are two of the most important ingredients of creative thinking, leading to more impactful results.", "Work to ensure that environments, buildings, and materials are accessible and inclusive. Look for these opportunities and stand up for them rather than being a bystander when you notice them."], "image": "data/images/15_DIVERSITY.jpg"}, {"id": 16, "name": "EDUCATION", "definition": "to engage in and appreciate teaching and learning", "actions": ["Take free or affordable classes and attend lectures on your favorite topics, online or in person.", "Give yourself a reading challenge each year, and set a reading goal for each month.", "Volunteer at schools and universities to help students and teachers in need of assistance.", "Serve on your local school board or attend school board meetings where you can influence others to improve your educational system.", "Advocate for educational equity for all people."], "image": "data/images/16_EDUCATION.jpg"}, {"id": 17, "name": "EMPATHY", "definition": "to be sensitive to and experience the feelings of others", "actions": ["Practice putting yourself in another’s shoes and imagining what they must be feeling or experiencing. When you have the opportunity, ask others what their experience is like, and listen without judgment.", "Listen to others without attempting to fix their pain. Make it a goal each day to listen without interrupting.", "Pay attention to how much you take on other people’s feelings or problems, so you don’t become overwhelmed.", "Express your empathy by becoming involved in a cause that aims to reduce the suffering of others.", "Challenge those who show bias or prejudice, and encourage others to consider the experiences of those who are different or who are struggling."], "image": "data/images/17_EMPATHY.jpg"}, {"id": 18, "name": "ENVIRONMENT", "definition": "to prioritize care for the Earth, our environment, and all living things through your actions", "actions": ["Do your research to understand environmental issues inside and out, and do your due diligence to make sure you’re sharing relevant and factual information with others.", "Start by working to improve environmental issues in your own home; track things like recycling, power usage, waste, and other habits that affect your own carbon footprint.", "Reframe your perspective to consider the planet as your other “home.”", "Remember that every voice counts! Use yours to inspire and encourage others to do their part.", "Be creative with your activism. Whether you’re sponsoring a fair or a competition, use your imagination to inspire others, especially children."], "image": "data/images/18_ENVIRONMENT.jpg"}, {"id": 19, "name": "EQUALITY", "definition": "to promote equal status, rights, and opportunities for all", "actions": ["Reflect on what equality means to you and how you arrived at the conclusions you’ve drawn based on your lived experience.", "Investigate history and how we got to a world where inequality is the norm.", "Model treating others fairly and ensuring that all people have equal access to opportunities.", "Pay special attention to moments we might take for granted, such as sight or access lines at movies or concerts, language nuances, or potential preferential treatment.", "Educate yourself on the skills necessary to challenge inequality and discrimination."], "image": "data/images/19_EQUALITY.jpg"}, {"id": 20, "name": "EXCELLENCE", "definition": "to strive for and achieve greatness and distinction", "actions": ["Make a list of all the areas in your life in which you already feel a sense of excellence.", "Make another list of areas in which you are striving for excellence, and write about what you think you need to do to attain excellence in each of those areas.", "Each day, ask yourself: “Did I give the best of myself to the world today?”", "Consider how you could give back to others in areas in which you’ve achieved excellence, through things like mentoring or teaching.", "Notice and acknowledge when someone in your life demonstrates a focus on excellence."], "image": "data/images/20_EXCELLENCE.jpg"}, {"id": 21, "name": "FAMILY", "definition": "to prioritize the health, well-being, and happiness of those in your family", "actions": ["Reflect on the small, daily moments that demonstrate your care for your family.", "Consider simple rituals and traditions that signify family togetherness, such as a regular Sunday night supper or a walk together every evening.", "If you live away from your family, focus on other people who fill that role in your physical vicinity, considering them your “chosen family.”", "If your family is small, consider inviting other close friends into your circle to widen your notion of family.", "Recognize that you might be a family of one, and nourish that relationship accordingly."], "image": "data/images/21_FAMILY.jpg"}, {"id": 22, "name": "FORGIVENESS", "definition": "to offer mercy and compassion to others, letting go of resentment", "actions": ["Write your own definition for forgiveness and what it means to you. Put it where you can access it regularly.", "Practice self-forgiveness; remember that in order to forgive others, it’s important to also release judgment of and forgive yourself.", "Practice being vulnerable and empathetic. The more we are in touch with our own pain, the more we’re able to forgive others.", "Give yourself time to forgive others when forgiveness feels too big or too hard."], "image": "data/images/22_FORGIVENESS.jpg"}, {"id": 23, "name": "FUN", "definition": "to engage in playfulness and amusement", "actions": ["Keep track of and reflect on what makes you happy. Begin to see fun and joy as your purpose versus an extravagance.", "Make enjoyment your goal each day. Ask yourself: “How can I bring joy into each moment?”", "Find and appreciate small, inexpensive, easy ways to have fun, and enlist those around you to join in.", "Be spontaneous and say yes to invitations to have fun with friends and family.", "Go off the technology grid regularly with others to enjoy human company without distraction."], "image": "data/images/23_FUN.jpg"}, {"id": 24, "name": "GENEROSITY", "definition": "to give liberally to others without expecting anything in return", "actions": ["Practice saying, “I have all I need to be safe and at peace and to experience happiness and joy.”", "Recognize that it’s our default to be generous, but we often override this natural inclination with questions and doubts.", "Note all the things you have to give, even when it seems like you have nothing.", "Choose to do one kind or helpful thing for someone every day, including yourself. It can be as simple as noticing and saying something positive. Notice how you feel inside when you do this.", "Notice when you feel yourself tipping into a sense of scarcity that makes you want to hoard. Consider how you might practice taking small steps to turn toward a sense of abundance."], "image": "data/images/24_GENEROSITY.jpg"}, {"id": 25, "name": "GENUINENESS", "definition": "to be sincere, free from pretense, affectation, or hypocrisy", "actions": ["Make a list of what makes you who you are; practice aligning your actions with your values.", "Be honest and forthright in your communication, to the extent it’s safe to do so.", "When you make a mistake, admit fault as soon as possible.", "Share generously of yourself. Share your knowledge and resources with others openly, and know that there is plenty to go around.", "Let go of the opinions of others so that you can focus on your own unique path."], "image": "data/images/25_GENUINENESS.jpg"}, {"id": 26, "name": "GRATITUDE", "definition": "to give heartfelt thanks and appreciation regularly and openly", "actions": ["Say thank you every day by keeping a gratitude journal for things big and small.", "Ask yourself each morning: “How and to whom can I express gratitude today?”", "Volunteer to give back to your community or to a cause you are thankful for.", "Make your gratitude practice social by expressing it over the phone or in person to people you encounter.", "Look for opportunities to learn from challenging experiences; sometimes challenges have the most to teach us."], "image": "data/images/26_GRATITUDE.jpg"}, {"id": 27, "name": "GROWTH", "definition": "to develop and change continually", "actions": ["Resist the urge to think of yourself as “smart” / “not smart” or “good” / “not good” at something. Instead, notice the hard work and effort you put toward improving yourself.", "Pursue interesting and challenging tasks in order to learn more, rather than to simply perform or achieve.", "Follow your deepest curiosities, those that intrigue you or represent gaps in your knowledge.", "Consider setbacks as opportunities to try something different rather than as obstacles that hinder progress.", "Remind yourself that growth is a continuous, ongoing process without a finish line."], "image": "data/images/27_GROWTH.jpg"}, {"id": 28, "name": "HARMONY", "definition": "to feel a sense of inner peace, calm, contentment, and serenity; to have harmonious relationships; and to have equilibrium in all areas of life", "actions": ["Do your best to focus on the happiness of your own life instead of monitoring or judging the lives of others.", "Think of every event not just as a success or failure but as an opportunity to learn and grow.", "Practice staying in the present moment instead of worrying about the future or lamenting the past.", "Choose relationships that support your mental and physical health.", "Prioritize time for yourself away from others for contemplation and replenishment."], "image": "data/images/28_HARMONY.jpg"}, {"id": 29, "name": "HEALTH", "definition": "to live in ways that promote overall wellness and vigor", "actions": ["Write down what it means to you to be healthy, then assess how you’re attending to your health in the areas you noted.", "Think about consistency. How often are you getting enough sleep, eating regular healthy meals, or moving your body?", "Surround yourself with other people who value health the way you do.", "Find a health mentor to whom you can be accountable for taking care of your health.", "Create new, healthier habits by setting different, manageable goals each month for any aspect of your health you can improve."], "image": "data/images/29_HEALTH.jpg"}, {"id": 30, "name": "HONESTY", "definition": "to be truthful, sincere, and frank", "actions": ["Practice pausing and taking a deep breath whenever you’re about to speak.", "Speak and write in straightforward, unambiguous language that allows others to understand clearly what you mean.", "Share with others the rationale behind your decisions so they understand your intent.", "Acknowledge and thank others when they tell you the truth.", "Ask yourself: “Am I maintaining healthy habits and relationships? If not, how can I be more honest with myself about what’s not working?”"], "image": "data/images/30_HONESTY.jpg"}, {"id": 31, "name": "HUMILITY", "definition": "to be humble and not think of yourself as better than others", "actions": ["Focus first on listening to others in every situation.", "Seek help when you don’t understand something or aren’t able to do something yourself.", "Solicit feedback on how you might do something better or be a better person in challenging situations.", "At work and in life, make an effort to seek out the opinion or perspective of the most junior or youngest person.", "Ask yourself: “How do my words and actions model humility for others?”"], "image": "data/images/31_HUMILITY.jpg"}, {"id": 32, "name": "HUMOR", "definition": "to have and appreciate a sense of amusement in yourself and others", "actions": ["Make a list of all the reasons humor benefits you and others. Set goals about infusing humor into your everyday life.", "Listen for and support through laughter and affirmation others’ attempts to be humorous.", "Evaluate your ability to have a sense of humor about yourself.", "Focus more on having a good time than on being the funny person in the room.", "Find humor in what connects us, not in what is hurtful to or diminishes other people."], "image": "data/images/32_HUMOR.jpg"}, {"id": 33, "name": "INCLUSIVENESS", "definition": "to practice being welcoming and ensuring a sense of belonging for all", "actions": ["Use language that includes everyone and is not gender-specific.", "Make space for and listen to others without interrupting or talking over them, especially when their style of communication is less dominant than yours.", "Get into the practice of recognizing your biases when you first meet someone.", "Avoid making assumptions about others whom you perceive to be either different from or similar to you.", "Be aware of your own privileges, and use that awareness as a lens for communicating about and with others."], "image": "data/images/33_INCLUSIVENESS.jpg"}, {"id": 34, "name": "INDEPENDENCE", "definition": "to act with free will based on your own desires and beliefs", "actions": ["Consider the extent to which you’re able to make decisions on your own, based on your own wants and needs, versus having to consult others.", "Make a list of all the things you admire about yourself, and use these attributes as the basis for how you behave and interact with others.", "Learn to offer yourself the support you need in times of emotional distress, but also know that being independent doesn’t mean you can’t rely on others.", "Practice self-acceptance so that you can weather tough times, hard decisions, and adversity by honoring your own needs, boundaries, and desires.", "Make a habit of expressing your own needs, boundaries, and desires."], "image": "data/images/34_INDEPENDENCE.jpg"}, {"id": 35, "name": "INTEGRITY", "definition": "to adhere to a practice of honesty and of having your outer world reflect your inner world; to be what you seem to be", "actions": ["Get to know your inner world more deeply through journaling and regular reflection, so you can better express yourself with honesty.", "Make a list of all the things you believe in, or create a personal mission statement for your life and work.", "Find ways to stay committed to your beliefs in your regular, everyday life—especially when it’s hard.", "Practice being transparent about your decisions and opinions.", "Know what it means to you to do the right thing even when no one’s paying attention."], "image": "data/images/35_INTEGRITY.jpg"}, {"id": 36, "name": "INTUITION", "definition": "to have and trust your own knowledge, independent of reasoning processes", "actions": ["Learn to listen to, trust, and act on your gut feelings.", "Balance gut feelings with common sense and rationality, especially when making big decisions.", "Allow yourself to feel and honor all your feelings instead of stuffing them away.", "Pay attention to your own energy in relation to your daily activities; keep track of how your energy changes based on who you’re with or what you’re doing.", "Find time each day to be silent and still and to listen to what’s going on inside you and what you need."], "image": "data/images/36_INTUITION.jpg"}, {"id": 37, "name": "JUSTICE", "definition": "to promote fair, equal, and balanced treatment for all", "actions": ["List all the ways you’re currently paying attention to how justice and injustice manifest in your life, both close to home and around the world.", "Evaluate the situations in which you might be a more just person, and support justice in the world.", "Plan activities that might support the goal of creating more justice; spread the word and get the conversation started.", "Get to know your neighbors and your community. Exposing yourself to others’ lived experiences will shed light on how your immediate connections experience justice.", "Volunteer your time working for justice in some area of society that you care about deeply."], "image": "data/images/37_JUSTICE.jpg"}, {"id": 38, "name": "KINDNESS", "definition": "to be warm, considerate, and benevolent toward others", "actions": ["Start by being kinder and gentler with yourself. How you treat yourself will often determine how you treat others.", "Practice giving people the benefit of the doubt before responding.", "Put yourself in the shoes of other people; empathy is a precursor to kindness.", "Keep a journal and ask yourself: “How have I been kind to others today? How have I been kind to myself?”", "Be especially mindful of how you do or don’t model kindness toward yourself and others in the presence of young people."], "image": "data/images/38_KINDNESS.jpg"}, {"id": 39, "name": "KNOWLEDGE", "definition": "to acquire and contribute information and skills through experience or education", "actions": ["List all the ways in which you actively absorb knowledge in your daily activities.", "Consider all the ways you could support the consumption of more knowledge in your daily activities. Think outside the box!", "Discover the types of knowledge you’re most interested in consuming, and make room in your life to learn more about these areas of interest. Remember, it doesn’t have to happen all at once!", "Think about ways you could contribute to the building of knowledge in areas that are most important to you.", "Consider all the ways you enjoy learning new things. Honor your own learning style by engaging with learning in ways that work best for you."], "image": "data/images/39_KNOWLEDGE.jpg"}, {"id": 40, "name": "LEADERSHIP", "definition": "to be in charge, guiding or leading others toward a goal", "actions": ["Deepen your knowledge of the key components of leadership, including communication, awareness, honesty/integrity, relationship-building, and innovation.", "Define your own leadership style and communicate it clearly to the people you lead, staying open to what you might learn and adjusting along the way.", "Be clear about what you’re leading toward. Always keep your eye on how things could be improved, and encourage people to move toward that vision.", "Understand that others may have different motivations, needs, and values. Try to weave them into the work you’re setting out to do as a leader.", "Don’t confuse leadership with popularity, power, title, or showmanship."], "image": "data/images/40_LEADERSHIP.jpg"}, {"id": 41, "name": "LOVE", "definition": "to treat others with closeness, warmth, and affection", "actions": ["Practice loving yourself first as the pathway to loving others more fully.", "Consider love as being made up of different elements, such as loving-kindness, understanding, offering joy, and empathy.", "At the end of each day, reflect on all the ways you’ve given or received love.", "Open yourself to vulnerability and intimacy with others by sharing deeper parts of yourself to create connection.", "Make a list of all the ways you’re personally able to share love and all the ways you best like to receive love from others. How are they similar or different?"], "image": "data/images/41_LOVE.jpg"}, {"id": 42, "name": "LOYALTY", "definition": "to desire and feel, and to offer to others, a strong sense of support or allegiance", "actions": ["Consider all the ways you show up consistently for others in your life, and how you offer others devotion.", "Ask someone close to you how they’d like to be supported and what loyalty means to them.", "Aim to be a good listener. You’ll begin to pick up on the needs of others as a way of supporting our ultimate human need, which is to feel understood.", "As a demonstration of loyalty, try to remember the little things people share with you, especially the things that someone might not even remember telling you.", "Think about returning loyalty when you notice it extended to you."], "image": "data/images/42_LOYALTY.jpg"}, {"id": 43, "name": "MINDFULNESS", "definition": "to focus awareness on the present moment", "actions": ["Think about mindfulness as an effort to not miss out on your life. When we’re living in our minds, preoccupied with memories of the past, thoughts and worries about the future, judgments, and reactions, we’re often only partially present in the now.", "Eat and walk mindfully. Focus all of your attention on what’s in front of you, the tastes and smells, the sights and sounds, trying not to be distracted by anything else.", "Pay attention to your breath, and connect with your senses. Put love and attention into each simple task of your day, which will bring you much joy and peace.", "Listen wholeheartedly, without planning what you’ll say next or judging what someone is saying, and without getting lost in your own thoughts.", "Notice when you’re doing something you really love, and allow yourself to get lost in the flow of that activity."], "image": "data/images/43_MINDFULNESS.jpg"}, {"id": 44, "name": "MODERATION", "definition": "to avoid excess or extremes; to live within reasonable limits", "actions": ["Think about moderation as a way of taking in the big picture and the long view of your life.", "Take small steps, bit by bit, and consider overall balance.", "Write down how your own life reflects a rational middle course and how you can work to improve moderation in your life.", "Realize that moderation can be learned and gained through experience and practice.", "Let go of the idea that things need to be perfect or complete."], "image": "data/images/44_MODERATION.jpg"}, {"id": 45, "name": "NON-CONFORMITY", "definition": "to question and challenge authority and norms", "actions": ["Reflect on what nonconformity means to you and why it feels important. List all the ways you feel you are a nonconformist in your everyday life.", "Explore norms in mainstream culture, and your perspectives on them, including where you think you fit in and where you do not.", "Model nonconformity by valuing opinions and ways of being that are different from your own.", "Work to find and honor what brings you joy, even if it seems to go against the grain of mainstream culture or your own family or cultural norms.", "Take responsibility for your choices, and embrace them as an expression of your own uniqueness."], "image": "data/images/45_NON_CONFORMITY.jpg"}, {"id": 46, "name": "OPENNESS", "definition": "to be open-minded to new experiences, ideas, and options", "actions": ["Reflect on how openness manifests in your current life, and then consider all the ways that your life restricts openness.", "Seek out a variety of experiences, and get comfortable with the unfamiliar. Be curious and embrace surprise and spontaneity.", "Remember that openness correlates to greater creativity, a more active imagination, and a greater appreciation for aesthetics and beauty.", "Evaluate how the relationships in your life support open and honest communication and how they don’t.", "Commit yourself each morning to one extra occurrence of openness, pushing beyond your comfort zone in some way. Notice how far you’ve come at the end of a week, a month, or a year."], "image": "data/images/46_OPENNESS.jpg"}, {"id": 47, "name": "OPTIMISM", "definition": "to practice hopefulness and confidence about the future and to expect successful outcomes", "actions": ["Visualize your best possible self, and sit and write about it for a few minutes once a week. Work your optimism “muscle,” making space to visualize your dreams manifesting, rather than imagining bad outcomes.", "Aim to have positive expectations, even if it means being proven wrong, rather than having negative expectations and sometimes being proven right.", "Keep an eye on the company you keep; negativity is contagious, and so are positive emotions.", "Acknowledge what you can and can’t control. Focus on what you have control over.", "Approach hardship in a productive way. Ask yourself: “What can I learn from this difficult situation?”"], "image": "data/images/47_OPTIMISM.jpg"}, {"id": 48, "name": "ORDER", "definition": "to live in a way that is organized, ordered, and structured", "actions": ["Be clear on your short- and long-term priorities, and make choices and decisions that keep them at the forefront.", "Take good care of your body and mind. Aim to nourish yourself, get solid sleep and exercise, and make an effort to keep your mind calm. Setting up a routine of good habits not only makes us feel better but also helps us feel some control over our lives.", "Pay attention to your surroundings, and make small tweaks to keep your living space tidy. Try to give everything a home, including your keys, wallet, and phone, and spend a few minutes every week decluttering so your living and working environments feel calmer.", "To minimize chaos and disorder, develop a system for tracking your daily tasks and appointments."], "image": "data/images/48_ORDER.jpg"}, {"id": 49, "name": "PARENTING", "definition": "to prioritize the rearing of children", "actions": ["Consider that parenting has multiple components, including ensuring health and safety, promoting emotional well-being, instilling social skills, encouraging intellectual preparation, and offering a loving environment.", "Write down your own parenting manifesto or ideals. Be clear with yourself and any caregivers about how you’d like to approach parenting so that it becomes consistent and thoughtful rather than reactionary.", "Combine warmth and sensitivity with clear behavioral expectations.", "Aim to be loving but firm, allowing enough space for each child to pursue their own interests, explore independence, and experience failure."], "image": "data/images/49_PARENTING.jpg"}, {"id": 50, "name": "PASSION", "definition": "to have the desire and the internal drive to obtain a specific goal, dream, or lifestyle", "actions": ["Reflect on what passion means to you and why it’s an important value. List the things you feel the most passion for, and perhaps consider how your passions have evolved over the course of your lifetime.", "Attempt to listen to your inner voice and ignore the noise around you telling you what you “should” do. Remember that your passions are what you would most want to do, or want to become, if you had no fear of failure or limits.", "Pay attention to what brings you joy and what makes you feel good. When you have passion for something, you love it even when it’s a chore.", "Consider all the passions you have that uplift you and push you through difficult times."], "image": "data/images/50_PASSION.jpg"}, {"id": 51, "name": "PATIENCE", "definition": "to have the capacity to accept or tolerate delay, trouble, or suffering without becoming upset", "actions": ["Consider that patience has several dimensions, including how you respond to interpersonal issues, life hardships, and daily hassles.", "Identify when you feel impatient and what emotion you’re feeling, then take a step back and reframe how you think about the situation to move to a more patient state of mind.", "Practice the habit of waiting patiently and calmly. Once you’ve gotten good at this simple step, you’ll be able to apply patience to other situations that are irritating.", "Take a few deep breaths several times a day; this practice has the physiological power to ease the body and the mind.", "Try cutting down on caffeine and other stimulants, which can exacerbate heightened responses to stressful situations."], "image": "data/images/51_PATIENCE.jpg"}, {"id": 52, "name": "PURPOSE", "definition": "to live life with meaning, intention, and direction", "actions": ["Consider purpose as striving toward something outside yourself that allows you to feel more connected.", "Recognize that a life of purpose requires planning, ownership of your actions, and responsibility for your choices and their consequences.", "Think about an action you can take in service of your purpose and then enact it.", "When you find yourself doubting your purpose, drop from your head into your heart and ask yourself what you love, what inspires you, what thrills you.", "Recognize that your purpose may have many elements and isn’t likely to be only “one thing.” Write down all the things in your life that give you a sense of purpose, and activate those that feel the most meaningful to you."], "image": "data/images/52_PURPOSE.jpg"}, {"id": 53, "name": "RATIONALITY", "definition": "to make decisions and choices based on and in accordance with data, reason, or logic", "actions": ["Start with the understanding that, as humans, we are programmed for irrational thought—that is, we tend to hold beliefs we want to believe and then find anything we can to support those beliefs.", "Focus on the facts, simplifying them as much as possible, to increase your rational responses.", "Explore the reasons for doing something before jumping to a choice or decision. Write those reasons down as a way to process them fully.", "Make decisions with a plan based on good evidence and a list of pros and cons."], "image": "data/images/53_RATIONALITY.jpg"}, {"id": 54, "name": "RESILIENCE", "definition": "to recover quickly from difficulties", "actions": ["Recognize that everyone’s life consists of everyday challenges and even traumatic events with lasting impact. Resilience includes both “bouncing back” quickly from these difficulties, along with deep personal work to learn and grow over the long term.", "Understand that becoming more resilient empowers you to handle future difficulties more adeptly.", "Build connections with understanding and empathetic people or groups, so you’re able to accept support when you need it.", "Foster physical and emotional resilience via proper nutrition, optimal sleep, hydration, and exercise, which will strengthen your body and allow it to adapt to stress."], "image": "data/images/54_RESILIENCE.jpg"}, {"id": 55, "name": "RESPECT", "definition": "to consistently offer to others, and to receive in exchange, regard for things like feelings, rights, traditions, abilities, qualities, or achievements", "actions": ["Recognize that respect is reciprocal; it’s both about how you treat others and how you expect others to treat you.", "Remember that respect is demonstrated by things like listening, affirming, and treating all of humanity with honor, dignity, care, and consideration.", "Model accepting others for who they are, even when they’re different from you or you don’t agree with them.", "Distinguish between disagreement and disrespect. Practice disagreeing and expressing your point of view in a respectful way."], "image": "data/images/55_RESPECT.jpg"}, {"id": 56, "name": "RESPONSIBILITY", "definition": "to be reliable and dependable and to hold yourself and others accountable for decisions and choices", "actions": ["Consciously make decisions and behave in ways that support improving yourself or helping others.", "Accept the consequences of your actions and decisions.", "Think clearly about what you have control over and what you don’t. This will help you determine what you can take responsibility for. Then communicate those boundaries with others in your life.", "Set routines for yourself to build permanent habits; routines lead to a more organized, responsible life."], "image": "data/images/56_RESPONSIBILITY.jpg"}, {"id": 57, "name": "RISK-TAKING", "definition": "to do things that involve some danger or risk in order to achieve a goal", "actions": ["Reframe risk as an opportunity to succeed rather than a path to failure.", "Prepare for and calculate the benefits and drawbacks of taking leaps.", "Stand out and be a leader rather than a follower satisfied with the status quo.", "Consider that risks often lead to new and important paths.", "Embrace risk-taking as a way to help overcome any fear of failure."], "image": "data/images/57_RISK_TAKING.jpg"}, {"id": 58, "name": "ROMANCE", "definition": "to have feelings and rituals associated with love or romantic ideals", "actions": ["If you have a partner, be fully present in the moment with them. When you’re fully present, you’re able to slow down, to notice, to nurture, to get in touch with whatever makes your partner feel loved.", "Begin by listening, observing, and writing down notes and reminders. Without realizing it, our partners tell us overtly how and what makes them feel good. We only have to pay attention.", "Bring surprise into your relationship by deviating from the normal course of your day, breaking up the typical routines.", "Put effort into celebrating even the smallest occasions in a thoughtful and novel way.", "Whether or not you have a partner, remember that it’s possible to nurture a sense of romance with what you read and listen to, how you dress, and where and how you travel."], "image": "data/images/58_ROMANCE.jpg"}, {"id": 59, "name": "SELF-AWARENESS", "definition": "to have conscious knowledge of your own character, feelings, motives, and desires", "actions": ["Reflect on your ability to see yourself clearly, to recognize your own emotional state at any time, and to see yourself as others see you.", "Begin by being curious about who you are and letting your walls down when you see something you don’t immediately like in yourself.", "Understand your early life story; write about the people, events, and experiences that had the greatest impact in shaping the person you’ve become.", "Make a daily habit of self-reflection. Take a few minutes each day to focus your attention on what’s really important to you; regularly check in with your sensory experience—how your body feels—and make adjustments accordingly.", "Ask trusted friends how they see you; choose friends who will act as an honest mirror and will want to help, not hurt. Take action to address some of your potential “blind spots.”"], "image": "data/images/59_SELF_AWARENESS.jpg"}, {"id": 60, "name": "SELF-DISCIPLINE", "definition": "to regulate yourself for the sake of improvement and overcome your weaknesses despite temptations", "actions": ["Consider self-discipline as a learned pattern of behavior in which, each day, you choose to do what you know is the right thing to do, rather than what you may want to do.", "Consider how you feel after you’ve been self-disciplined, and use this feeling to motivate you to be more self-disciplined in the future.", "Know and acknowledge your weaknesses and shortcomings; owning up to them is the first step toward overcoming them.", "Remove temptations. If you want to eat better, don’t buy junk food. If you want to be more productive, silence your phone and block notifications.", "When you fall short, forgive yourself and continue moving forward."], "image": "data/images/60_SELF_DISCIPLINE.jpg"}, {"id": 61, "name": "SELF-EXPRESSION", "definition": "to express your personality, individuality, beliefs, and needs", "actions": ["Reflect on how often and in what ways you currently share yourself—and your talents, personality, and gifts—with others.", "Consider how your body language, speech, clothing, interests, and passions are expressions of your personality and individuality.", "Talk with a loved one about which of your qualities they feel are the most vibrant and most representative of your true self.", "Consider that self-expression is demonstrated outwardly; it is not an inner need to seek acceptance."], "image": "data/images/61_SELF_EXPRESSION.jpg"}, {"id": 62, "name": "SELF-RESPECT", "definition": "to accept yourself and have pride and confidence in yourself as a human being, and to treat yourself accordingly, with honor and dignity", "actions": ["Know that you are a unique, special, and valuable person who is worthy of being treated with love and respect.", "Pay special attention to your personal hygiene, and wear clean clothes that make you feel good about yourself. How you present yourself impacts how you feel about yourself.", "Make your living space clean, comfortable, and attractive. Surround yourself with items that make you feel good and remind you of special times and people.", "Do things that bring you joy each day, even if you need to do them alone.", "Identify and challenge any negative thoughts about yourself. Avoid people and places that make you feel bad. Stay away from people who don’t treat you well."], "image": "data/images/62_SELF_RESPECT.jpg"}, {"id": 63, "name": "SERVICE", "definition": "to help or do work for the benefit of others", "actions": ["Remember that honoring your need for service will give you a stronger sense of purpose and meaning, which leads to better mental and physical well-being.", "Before offering service to others, find out what they actually need; make an effort to first ask what would be helpful rather than assuming.", "Start with what you’re naturally good at and what you enjoy doing. Then think of one person or group that would benefit from your skills and labor, and reach out to them.", "Model service. Helping others is contagious; when one person does a good deed, it causes a chain reaction of other helpful acts, which can then ripple throughout a community and make a collective impact."], "image": "data/images/63_SERVICE.jpg"}, {"id": 64, "name": "SIMPLICITY", "definition": "to live in an uncomplicated, unpretentious way", "actions": ["Consider simplicity as the mind-set of being satisfied with what you have.", "Keep track for a month of where you spend the most time in your home and what you wear the most. Then consider whether you can simplify your living space and streamline your wardrobe, which will improve your finances and give you more free time. Focus on the essentials—what’s most important to you—rather than getting bogged down with material things.", "Save your money in an emergency fund so you have breathing room to make more intentional decisions when they arise.", "Periodically, assess who you’re spending time with and whether that time is valuable to you; make modifications accordingly.", "Recognize that your individual behavior can inspire others and collectively add up to significant change."], "image": "data/images/64_SIMPLICITY.jpg"}, {"id": 65, "name": "SOCIAL CONNECTION", "definition": "to prioritize close and ongoing relationships with other people", "actions": ["Try saying hello to people as you go about your day; ask how someone is, and really listen to their response.", "Consider getting involved in something larger than yourself; work at a food bank or tutor a student.", "Offer a moment of connection to someone who might need it—perhaps someone who lives alone or is elderly.", "Build connections by telling short personal stories that admit your vulnerabilities and share your humor with others.", "Create shared rituals with friends and family, whether it’s regular Sunday suppers or phone dates with someone who lives far away."], "image": "data/images/65_SOCIAL_CONNECTION.jpg"}, {"id": 66, "name": "SOLITUDE", "definition": "to have ample time and space apart from others", "actions": ["Reframe solitude to mean “making friends with yourself.”", "Consider setting your alarm fifteen to thirty minutes earlier than usual, and spend that first part of the day alone in reflection or meditation.", "On your lunch break, sit somewhere for five minutes, close your eyes, and listen to the sound of your breath.", "Don’t plan anything on one weekend, and see what unfolds.", "Once a month, take yourself out on a date; schedule something you love to do, but do it on your own—perhaps a long walk, a meal, or another activity you enjoy."], "image": "data/images/66_SOLITUDE.jpg"}, {"id": 67, "name": "SPIRITUALITY", "definition": "to recognize and celebrate a power greater than yourself, grounded in love", "actions": ["Create your own definition of what spirituality means to you and own your own version of spiritual practice.", "Make an effort to connect with others who have similar spiritual views in order to benefit from community practice, like learning or meditating together.", "Prioritize time in your schedule for your spiritual practice, whether it’s prayer, meditation, or journaling.", "Work to align your behavior, attitudes, and actions with your spiritual principles or beliefs."], "image": "data/images/67_SPIRITUALITY.jpg"}, {"id": 68, "name": "STABILITY", "definition": "to have a life that stays fairly consistent", "actions": ["Consider how you ensure stability in your life; reflect on how you respond to uncertainty or chaos, and what practices and principles you use to remain stable.", "Reflect on all the ways your life is currently aligned with your need for stability, and all the ways in which it isn’t.", "Make a list of things that make a stable life, and consider how many of them you have in place.", "Ask yourself what impedes stability in your life and how you can work toward more consistency."], "image": "data/images/68_STABILITY.jpg"}, {"id": 69, "name": "SUCCESS", "definition": "to attain a particular goal, as measured by wealth, position, accomplishments, or honors", "actions": ["Focus on your commitment to your goals first and foremost; if you find that you are committed, your motivation will come naturally.", "Keep your energy focused on what draws you in and keeps you going, whether it’s knowledge or joy or the creative process, not on how quickly you meet your goals.", "Work to move past limiting beliefs about your ability to be successful.", "Keep moving; set goals, make a plan, and take specific action that will lead you to your goals, even if those steps are small and incremental.", "Surround yourself with people who will cheer you on and not be envious of, or threatened by, your wins."], "image": "data/images/69_SUCCESS.jpg"}, {"id": 70, "name": "THRIFT", "definition": "to use money and other resources carefully and not wastefully", "actions": ["Make a list of all the ways you currently employ thriftiness in your life.", "Reflect on all the ways that you would like to practice more thrift, and set goals for enacting new life practices that reflect those desires.", "Create a “Do I need this?” list, and whenever you want to buy something, add it to the list. Regularly evaluate your potential purchases through the lens of whether you need the item or not, and resist impulse buys that are not on the list.", "Eliminate luxuries like cable TV, a daily latte at your favorite coffee shop, or a wine club subscription in favor of a more frugal option, like a library card or a walking date with friends."], "image": "data/images/70_THRIFT.jpg"}, {"id": 71, "name": "VULNERABILITY", "definition": "to honor uncertainty, risk, and emotional exposure in yourself and others", "actions": ["Admit when you don’t know something or when you’ve made a mistake. Doing so can make people feel safer with you, knowing you won’t judge them for being imperfect.", "Regularly put yourself in the position of being a beginner by trying something new and challenging.", "Push through fear of criticism or disapproval by asking for feedback in order to change negative behavior.", "Make eye contact; avoiding eye contact is how we protect ourselves, which can cause disconnection from others. When you make eye contact, you’re saying, “I care and I’m listening.”", "Be the first to apologize. An apology shows that your connection with the other person means more to you than “winning” the argument."], "image": "data/images/71_VULNERABILITY.jpg"}, {"id": 72, "name": "WISDOM", "definition": "to have deep insight, knowledge, and judgment", "actions": ["Spend time acquiring knowledge by listening to others and intentionally learning from life experiences.", "Shine the spotlight on others, paying attention to and learning from what they do, how they do it, and why.", "Use every life experience, even painful ones, to learn and grow, and to change negative or unhelpful patterns of behavior.", "As you interact with others, approach them from a place of compassion and empathy; putting yourself in other people’s shoes is an excellent tool for developing wisdom."], "image": "data/images/72_WISDOM.jpg"}, {"id": 73, "name": "WORK ETHIC", "definition": "to demonstrate the desire and determination to work hard", "actions": ["Define your personal work ethic: What is your work ethic, and why is it important to you?", "Tend to your physical and emotional health so that you have the energy to keep up with your work.", "Set specific goals to focus on so you will gain a sense of accomplishment as you complete tasks.", "Avoid distractions to keep your focus on accomplishing your tasks and meeting your goals.", "Model self-initiated dependability and productivity by developing your own systems for getting work done and meeting deadlines."], "image": "data/images/73_WORK_ETHIC.jpg"}];
